fn first_word(text: &str) -> &str {
    match text.find(' ') {
        Some(i) => &text[..i],
        None => text,
    }
}

fn last_word(text: &str) -> &str {
    let t = text.trim_end();
    match t.rfind(' ') {
        Some(i) => &t[i + 1..],
        None => t,
    }
}

fn trim_zeros(values: &[i32]) -> &[i32] {
    let mut start = 0;
    let mut end = values.len();
    while start < end && values[start] == 0 {
        start += 1;
    }
    while end > start && values[end - 1] == 0 {
        end -= 1;
    }
    &values[start..end]
}

fn max_window_sum(values: &[i32], k: usize) -> Option<i32> {
    if k == 0 || k > values.len() {
        return None;
    }
    let mut best = i32::MIN;
    for window in values.windows(k) {
        let sum: i32 = window.iter().sum();
        if sum > best {
            best = sum;
        }
    }
    Some(best)
}

fn split_on(values: &[i32], separator: i32) -> Vec<&[i32]> {
    let mut parts = Vec::new();
    let mut start = 0;
    for (i, &v) in values.iter().enumerate() {
        if v == separator {
            parts.push(&values[start..i]);
            start = i + 1;
        }
    }
    parts.push(&values[start..]);
    parts
}

unitTests:
test("words", || {
    let text = String::from("the quick brown fox");
    check_eq(first_word(&text), "the");
    check_eq(last_word(&text), "fox");
    check_eq(first_word("single"), "single");
    check_eq(last_word("trailing spaces   "), "spaces");
    let first = first_word(&text);
    check(std::ptr::eq(first.as_ptr(), text.as_ptr()));
});

test("trimming zeros", || {
    check_eq(trim_zeros(&[0, 0, 1, 0, 2, 0]), &[1, 0, 2]);
    check_eq(trim_zeros(&[0, 0]), &[] as &[i32]);
    check_eq(trim_zeros(&[5]), &[5]);
});

test("window sums", || {
    check_eq(max_window_sum(&[1, 3, -2, 5, 1, -9], 2), Some(6));
    check_eq(max_window_sum(&[1, 3, -2, 5, 1, -9], 6), Some(-1));
    check_eq(max_window_sum(&[-5, -2, -8], 1), Some(-2));
    check_eq(max_window_sum(&[1, 2], 3), None);
    check_eq(max_window_sum(&[1, 2], 0), None);
});

test("splitting", || {
    let parts = split_on(&[1, 0, 2, 3, 0, 0, 4], 0);
    check_eq(parts, vec![&[1][..], &[2, 3][..], &[][..], &[4][..]]);
    check_eq(split_on(&[], 0), vec![&[] as &[i32]]);
    check_eq(split_on(&[7, 8], 0).len(), 1);
});

